def qident(value):
    return '"' + value.replace('"', '""') + '"'


def qliteral(value):
    return "'" + str(value).replace("'", "''") + "'"


def load_stage(con, name, columns, csv_path):
    definitions = ", ".join(f"{qident(column)} VARCHAR" for column in columns.split())
    con.execute(f"CREATE OR REPLACE TEMP TABLE {qident(name)} ({definitions})")
    con.execute(
        f"COPY {qident(name)} FROM {qliteral(csv_path)} "
        "(DELIMITER ';', HEADER FALSE, QUOTE '\"', ESCAPE '\"', NULL '')"
    )
    count = con.execute(f"SELECT COUNT(*) FROM {qident(name)}").fetchone()[0]
    print(f"staging local {name}: {count:,} linhas", flush=True)
    return count


def main():
    started = time.monotonic()
    zip_root = Path("/tmp/tse_full_2018_2024")
    stage_root = Path("/tmp/tse_motherduck_stage")
    shutil.rmtree(zip_root, ignore_errors=True)
    shutil.rmtree(stage_root, ignore_errors=True)
    zip_root.mkdir(parents=True)
    stage_root.mkdir(parents=True)

    source_manifest = acquire_sources(zip_root)
    namespace = {"__name__": "tse_normalizer", "__file__": "/tmp/normalizer.py"}
    exec(compile(NORMALIZER_SOURCE, "/tmp/normalizer.py", "exec"), namespace)
    sys.argv = ["normalizer.py", "--zip-dir", str(zip_root), "--output", str(stage_root)]
    namespace["main"]()

    normalizer_manifest = json.loads((stage_root / "manifest.json").read_text(encoding="utf-8"))
    con = duckdb.connect("md:")
    con.execute(f"CREATE DATABASE IF NOT EXISTS {qident(DB)}")
    con.execute(f"USE {qident(DB)}")

    counts = {}
    for table, columns in STAGE_COLUMNS.items():
        counts[table] = load_stage(con, table, columns, stage_root / STAGE_FILES[table])

    # Todas as transformacoes acontecem apos os CSVs passarem por CRC no parser.
    con.execute(MODEL_SQL)
    con.execute(VIEWS_SQL)

    expected_tables = {
        "municipio", "candidato", "partido", "candidatura", "bens_declarados",
        "receitas_campanha", "despesas_pagas", "perfil_eleitorado",
        "comparecimento_municipio", "votacao_partido", "votacao_candidato_municipio",
    }
    actual_tables = {
        row[0] for row in con.execute(
            "SELECT table_name FROM information_schema.tables "
            "WHERE table_schema='public' AND table_type='BASE TABLE'"
        ).fetchall()
    }
    if actual_tables != expected_tables:
        raise RuntimeError(f"Esquema final inesperado; tabelas: {sorted(actual_tables)}")
    expected_views = {
        "v_partidos_eleitos", "v_gasto_sucesso", "v_historico_candidato",
        "vw_questao_2_despesas",
    }
    actual_views = {
        row[0] for row in con.execute(
            "SELECT table_name FROM information_schema.views WHERE table_schema='public'"
        ).fetchall()
    }
    if actual_views != expected_views:
        raise RuntimeError(f"Views finais inesperadas: {sorted(actual_views)}")

    table_counts = {}
    for table in sorted(expected_tables):
        table_counts[table] = con.execute(
            f"SELECT COUNT(*) FROM public.{qident(table)}"
        ).fetchone()[0]
    q2_rows = con.execute("SELECT COUNT(*) FROM public.vw_questao_2_despesas").fetchone()[0]
    report = {
        "source": "Portal de Dados Abertos do TSE / API CKAN",
        "years": YEARS,
        "ufs": UFS,
        "source_archives": source_manifest,
        "normalizer": normalizer_manifest,
        "staging_rows": counts,
        "published_tables": table_counts,
        "published_views": sorted(actual_views),
        "q2_view_rows": q2_rows,
        "elapsed_seconds": round(time.monotonic() - started, 1),
    }
    print("MOTHERDUCK_LOAD_REPORT=" + json.dumps(report, ensure_ascii=False), flush=True)
    con.close()
    shutil.rmtree(zip_root, ignore_errors=True)
    shutil.rmtree(stage_root, ignore_errors=True)


if __name__ == "__main__":
    main()
